<body>
  <div class="container">
    <header>
      <h1>Falling Sand</h1>
      <div class="subtitle">Cellular Automata Sandbox</div>
    </header>

    <div class="canvas-wrapper">
      <canvas id="sand" width="100" height="100"></canvas>
    </div>

    <div class="toolbar">
      <div class="btn-group">
        <button id="mat-sand" class="active"><span class="dot"></span>Sand</button>
        <button id="mat-water"><span class="dot"></span>Water</button>
        <button id="mat-wall"><span class="dot"></span>Wall</button>
        <button id="mat-acid"><span class="dot"></span>Acid</button>
        <button id="mat-empty"><span class="dot"></span>Eraser</button>
      </div>
      <div class="divider"></div>
      <button id="clear">Clear</button>
      <div class="divider"></div>
      <div class="brush-control">
        <span>Size</span>
        <input type="range" id="brush-size" min="1" max="5" value="2">
        <span id="brush-val">2</span>
      </div>
    </div>
  </div>

  <script>
    (function () {
      const W = 100;
      const H = 100;

      const MAT_EMPTY = 0;
      const MAT_SAND = 1;
      const MAT_WATER = 2;
      const MAT_WALL = 3;
      const MAT_ACID = 4;

      const MAT_NAMES = ["empty", "sand", "water", "wall", "acid"];
      const MAT_IDS = {
        empty: MAT_EMPTY,
        sand: MAT_SAND,
        water: MAT_WATER,
        wall: MAT_WALL,
        acid: MAT_ACID,
      };

      const grid = new Uint8Array(W * H);
      const stepGrid = new Int32Array(W * H);
      const noise = new Int8Array(W * H);
      for (let i = 0; i < W * H; i++) {
        noise[i] = (Math.random() * 16 - 8) | 0;
      }

      let currentStepId = 0;
      let activeMat = MAT_SAND;
      let brushRadius = 2;
      let isPainting = false;
      let lastPaintPos = null;

      const canvas = document.getElementById("sand");
      const ctx = canvas.getContext("2d");
      const imgData = ctx.createImageData(W, H);
      const data32 = new Uint32Array(imgData.data.buffer);

      function markMoved(x, y) {
        stepGrid[y * W + x] = currentStepId;
      }

      function findLiquidEscape(sandX, sandY, liqX, liqY, isPouring) {
        const dirs = Math.random() < 0.5 ? [-1, 1] : [1, -1];
        for (let d of dirs) {
          let nx = sandX + d;
          if (nx >= 0 && nx < W) {
            if (grid[sandY * W + nx] === MAT_EMPTY) return { x: nx, y: sandY };
            if (sandY - 1 >= 0 && grid[(sandY - 1) * W + nx] === MAT_EMPTY) return { x: nx, y: sandY - 1 };
            if (liqY < H && grid[liqY * W + nx] === MAT_EMPTY) return { x: nx, y: liqY };
          }
        }
        for (let r = 2; r < W; r++) {
          for (let d of dirs) {
            let nx = sandX + d * r;
            if (nx >= 0 && nx < W) {
              for (let dy = 0; dy >= -r && sandY + dy >= 0; dy--) {
                let ny = sandY + dy;
                if (grid[ny * W + nx] === MAT_EMPTY) {
                  return { x: nx, y: ny };
                }
              }
            }
          }
        }
        return null;
      }

      function updateSand(x, y) {
        const dirs = Math.random() < 0.5 ? [-1, 1] : [1, -1];

        // 1. Straight down
        if (y + 1 < H) {
          const below = grid[(y + 1) * W + x];
          if (below === MAT_EMPTY) {
            grid[(y + 1) * W + x] = MAT_SAND;
            markMoved(x, y + 1);
            grid[y * W + x] = MAT_EMPTY;
            return;
          } else if (below === MAT_WATER || below === MAT_ACID) {
            const isPouring = (y - 1 >= 0 && grid[(y - 1) * W + x] === MAT_SAND);
            const esc = findLiquidEscape(x, y, x, y + 1, isPouring);
            if (esc) {
              grid[esc.y * W + esc.x] = below;
              markMoved(esc.x, esc.y);
              grid[(y + 1) * W + x] = MAT_SAND;
              markMoved(x, y + 1);
              grid[y * W + x] = MAT_EMPTY;
              return;
            } else if (!isPouring) {
              grid[(y + 1) * W + x] = MAT_SAND;
              markMoved(x, y + 1);
              grid[y * W + x] = below;
              markMoved(x, y);
              return;
            }
          }
        }

        // 2. Diagonal down
        if (y + 1 < H) {
          for (let d of dirs) {
            let nx = x + d;
            let ny = y + 1;
            if (nx >= 0 && nx < W) {
              const diag = grid[ny * W + nx];
              if (diag === MAT_EMPTY) {
                grid[ny * W + nx] = MAT_SAND;
                markMoved(nx, ny);
                grid[y * W + x] = MAT_EMPTY;
                return;
              } else if (diag === MAT_WATER || diag === MAT_ACID) {
                if (grid[y * W + nx] === MAT_EMPTY) {
                  grid[y * W + nx] = diag;
                  markMoved(nx, y);
                  grid[ny * W + nx] = MAT_SAND;
                  markMoved(nx, ny);
                  grid[y * W + x] = MAT_EMPTY;
                  return;
                } else if (y - 1 < 0 || grid[(y - 1) * W + x] !== MAT_SAND) {
                  grid[ny * W + nx] = MAT_SAND;
                  markMoved(nx, ny);
                  grid[y * W + x] = diag;
                  markMoved(x, y);
                  return;
                }
              }
            }
          }
        }
      }

      function updateWater(x, y) {
        const dirs = Math.random() < 0.5 ? [-1, 1] : [1, -1];

        // 1. Straight down
        if (y + 1 < H && grid[(y + 1) * W + x] === MAT_EMPTY) {
          grid[(y + 1) * W + x] = MAT_WATER;
          markMoved(x, y + 1);
          grid[y * W + x] = MAT_EMPTY;
          return;
        }

        // 2. Diagonal down
        if (y + 1 < H) {
          for (let d of dirs) {
            let nx = x + d;
            let ny = y + 1;
            if (nx >= 0 && nx < W && grid[ny * W + nx] === MAT_EMPTY) {
              grid[ny * W + nx] = MAT_WATER;
              markMoved(nx, ny);
              grid[y * W + x] = MAT_EMPTY;
              return;
            }
          }
        }

        // 3. Horizontal spread
        for (let d of dirs) {
          let nx = x + d;
          if (nx >= 0 && nx < W && grid[y * W + nx] === MAT_EMPTY) {
            grid[y * W + nx] = MAT_WATER;
            markMoved(nx, y);
            grid[y * W + x] = MAT_EMPTY;
            return;
          }
        }
      }

      function updateAcid(x, y) {
        // Dissolve sand or wall below or beside
        if (y + 1 < H) {
          const below = grid[(y + 1) * W + x];
          if (below === MAT_SAND || below === MAT_WALL) {
            grid[(y + 1) * W + x] = MAT_EMPTY;
            grid[y * W + x] = MAT_EMPTY;
            return;
          }
        }

        const dirs = Math.random() < 0.5 ? [-1, 1] : [1, -1];
        for (let d of dirs) {
          let nx = x + d;
          if (nx >= 0 && nx < W) {
            const side = grid[y * W + nx];
            if (side === MAT_SAND || side === MAT_WALL) {
              grid[y * W + nx] = MAT_EMPTY;
              grid[y * W + x] = MAT_EMPTY;
              return;
            }
          }
        }

        // Move like water
        // 1. Straight down
        if (y + 1 < H && grid[(y + 1) * W + x] === MAT_EMPTY) {
          grid[(y + 1) * W + x] = MAT_ACID;
          markMoved(x, y + 1);
          grid[y * W + x] = MAT_EMPTY;
          return;
        }

        // 2. Diagonal down
        if (y + 1 < H) {
          for (let d of dirs) {
            let nx = x + d;
            let ny = y + 1;
            if (nx >= 0 && nx < W && grid[ny * W + nx] === MAT_EMPTY) {
              grid[ny * W + nx] = MAT_ACID;
              markMoved(nx, ny);
              grid[y * W + x] = MAT_EMPTY;
              return;
            }
          }
        }

        // 3. Horizontal spread
        for (let d of dirs) {
          let nx = x + d;
          if (nx >= 0 && nx < W && grid[y * W + nx] === MAT_EMPTY) {
            grid[y * W + nx] = MAT_ACID;
            markMoved(nx, y);
            grid[y * W + x] = MAT_EMPTY;
            return;
          }
        }
      }

      function step() {
        currentStepId++;
        // Bottom-row-up scanning
        for (let y = H - 1; y >= 0; y--) {
          const leftToRight = ((currentStepId + y) & 1) === 0;
          const startX = leftToRight ? 0 : W - 1;
          const endX = leftToRight ? W : -1;
          const stepX = leftToRight ? 1 : -1;

          for (let x = startX; x !== endX; x += stepX) {
            if (stepGrid[y * W + x] === currentStepId) continue;
            const mat = grid[y * W + x];
            if (mat === MAT_EMPTY || mat === MAT_WALL) continue;
            if (mat === MAT_SAND) updateSand(x, y);
            else if (mat === MAT_WATER) updateWater(x, y);
            else if (mat === MAT_ACID) updateAcid(x, y);
          }
        }
      }

      function render() {
        let i = 0;
        for (let y = 0; y < H; y++) {
          for (let x = 0; x < W; x++, i++) {
            const mat = grid[i];
            const n = noise[i];
            let r = 18, g = 18, b = 24;

            if (mat === MAT_SAND) {
              r = 229 + n;
              g = 193 + (n >> 1);
              b = 88;
            } else if (mat === MAT_WATER) {
              r = 55;
              g = 140 + n;
              b = 230 + n;
            } else if (mat === MAT_WALL) {
              r = 136 + n;
              g = 141 + n;
              b = 158 + n;
            } else if (mat === MAT_ACID) {
              r = 75 + n;
              g = 235 + n;
              b = 50;
            }

            data32[i] = (255 << 24) | ((b & 255) << 16) | ((g & 255) << 8) | (r & 255);
          }
        }
        ctx.putImageData(imgData, 0, 0);
      }

      // Public programmatic API
      window.sim = {
        w: W,
        h: H,
        tick: function (n) {
          const count = typeof n === "number" ? n : 1;
          for (let i = 0; i < count; i++) {
            step();
          }
          render();
        },
        get: function (x, y) {
          if (x < 0 || x >= W || y < 0 || y >= H) return "wall";
          return MAT_NAMES[grid[y * W + x]] || "empty";
        },
        set: function (x, y, material) {
          if (x < 0 || x >= W || y < 0 || y >= H) return;
          const id = MAT_IDS[material];
          if (id !== undefined) {
            grid[y * W + x] = id;
            render();
          }
        },
        clear: function () {
          grid.fill(MAT_EMPTY);
          render();
        }
      };

      // UI and interaction
      function setActiveButton(btnId) {
        const buttons = ["mat-sand", "mat-water", "mat-wall", "mat-acid", "mat-empty"];
        buttons.forEach(id => {
          const el = document.getElementById(id);
          if (el) el.classList.toggle("active", id === btnId);
        });
      }

      document.getElementById("mat-sand").addEventListener("click", () => { activeMat = MAT_SAND; setActiveButton("mat-sand"); });
      document.getElementById("mat-water").addEventListener("click", () => { activeMat = MAT_WATER; setActiveButton("mat-water"); });
      document.getElementById("mat-wall").addEventListener("click", () => { activeMat = MAT_WALL; setActiveButton("mat-wall"); });
      document.getElementById("mat-acid").addEventListener("click", () => { activeMat = MAT_ACID; setActiveButton("mat-acid"); });
      document.getElementById("mat-empty").addEventListener("click", () => { activeMat = MAT_EMPTY; setActiveButton("mat-empty"); });
      document.getElementById("clear").addEventListener("click", () => window.sim.clear());

      const brushSlider = document.getElementById("brush-size");
      const brushVal = document.getElementById("brush-val");
      brushSlider.addEventListener("input", (e) => {
        brushRadius = parseInt(e.target.value, 10);
        brushVal.textContent = brushRadius;
      });

      function getCoords(e) {
        const rect = canvas.getBoundingClientRect();
        const clientX = e.clientX !== undefined ? e.clientX : (e.touches && e.touches[0] ? e.touches[0].clientX : 0);
        const clientY = e.clientY !== undefined ? e.clientY : (e.touches && e.touches[0] ? e.touches[0].clientY : 0);
        const scaleX = W / rect.width;
        const scaleY = H / rect.height;
        const x = Math.floor((clientX - rect.left) * scaleX);
        const y = Math.floor((clientY - rect.top) * scaleY);
        return {
          x: Math.max(0, Math.min(W - 1, x)),
          y: Math.max(0, Math.min(H - 1, y))
        };
      }

      function paintSpot(cx, cy) {
        const r = brushRadius - 1;
        if (r <= 0) {
          grid[cy * W + cx] = activeMat;
          return;
        }
        for (let dy = -r; dy <= r; dy++) {
          for (let dx = -r; dx <= r; dx++) {
            if (dx * dx + dy * dy <=
